import{_ as r,o as t,c as o,aO as d}from"./chunks/framework.vjUPZZJn.js";const q=JSON.parse('{"title":"readerwriterqueue：C++ SPSC 无锁队列上手","description":"","frontmatter":{"date":"2026-10-28T09:50:00.000Z","title":"readerwriterqueue：C++ SPSC 无锁队列上手","source":[["1-知识/C++/并发组件/SPSC 无锁队列"]],"tags":["编程语言","学习笔记","C++","并发编程"],"categories":["计算机"],"permalink":"/pages/a20f92"},"headers":[],"relativePath":"计算机/readerwriterqueue：C++ SPSC 无锁队列上手.md","filePath":"计算机/readerwriterqueue：C++ SPSC 无锁队列上手.md","lastUpdated":1793240540000}'),a={name:"计算机/readerwriterqueue：C++ SPSC 无锁队列上手.md"};function c(i,e,u,l,n,s){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="readerwriterqueue-c-spsc-无锁队列上手" tabindex="-1">readerwriterqueue：C++ SPSC 无锁队列上手 <a class="header-anchor" href="#readerwriterqueue-c-spsc-无锁队列上手" aria-label="Permalink to &quot;readerwriterqueue：C++ SPSC 无锁队列上手&quot;">​</a></h1> <p>两个固定角色的线程之间单向传递数据——一个线程只生产、一个线程只消费——是并发程序里最常见的协作形态，例如采集线程持续产生样本、处理线程顺序消费。这类场景用单生产者单消费者（SPSC）队列最合适，而手写无锁实现需要正确处理空满区分与内存序配对，出错后往往表现为偶发数据错乱，难以定位。readerwriterqueue 是一个专注 SPSC 场景的 C++11 无锁队列库，两个头文件即插即用，接口与 <code>std::queue</code> 接近。本文介绍它的设计特性、三种队列类型、使用要点与集成方式，适合需要在两个线程间高频传数据、又不想手写无锁结构的开发者。</p> <h2 id="库概览" tabindex="-1">库概览 <a class="header-anchor" href="#库概览" aria-label="Permalink to &quot;库概览&quot;">​</a></h2> <ul><li>项目地址：<a href="https://github.com/cameron314/readerwriterqueue" target="_blank" rel="noreferrer">https://github.com/cameron314/readerwriterqueue</a></li> <li>作者：cameron314（多生产者多消费者库 ConcurrentQueue 的同一作者）</li> <li>许可：简化版 BSD（simplified BSD）</li> <li>核心文件：<code>readerwriterqueue.h</code> 与 <code>atomicops.h</code> 两个头文件，命名空间 <code>moodycamel</code></li></ul> <p><code>atomicops.h</code> 是跨编译器的原子操作与内存屏障抽象层，分别对接 GCC/Clang 的 <code>__atomic_thread_fence</code>、MSVC 的 <code>_ReadWriteBarrier</code> 与 ICC 的内建函数，保证不同编译器下内存序语义一致；队列本体的全部逻辑在 <code>readerwriterqueue.h</code>。</p> <h2 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h2> <ol><li><strong>角色固定</strong>：整个队列只服务一个生产者线程加一个消费者线程，线程角色不可切换。这是它能把性能做到极致的前提。</li> <li><strong>无锁且无等待</strong>：入队与出队没有比较并交换（CAS）循环，每次操作都在有限的指令步内完成，复杂度 O(1)；在 x86 等强内存模型架构上，内存屏障会被编译为空操作，热路径只剩普通的加载、存储与分支。</li> <li><strong>通用模板</strong>：像 <code>std::queue</code> 一样容纳任意类型并内部管理内存，支持移动语义与原地构造（<code>try_emplace</code>/<code>emplace</code>），避免不必要的拷贝。</li> <li><strong>内存行为可预期</strong>：构造时预分配连续内存，缓存友好；<code>try_enqueue</code> 保证在初始容量内绝不分配内存，适合实时性敏感的调用路径；<code>enqueue</code> 则在队列满时自动扩容。</li> <li><strong>窥视支持</strong>：<code>peek()</code> 允许消费者查看队首元素而不出队。</li></ol> <h2 id="三种队列类型" tabindex="-1">三种队列类型 <a class="header-anchor" href="#三种队列类型" aria-label="Permalink to &quot;三种队列类型&quot;">​</a></h2> <table tabindex="0"><thead><tr><th>类别</th> <th>形态</th> <th>关键接口</th></tr></thead> <tbody><tr><td><code>ReaderWriterQueue&lt;T&gt;</code></td> <td>基础版，可扩容</td> <td><code>enqueue</code>、<code>try_enqueue</code>、<code>try_dequeue</code>、<code>peek</code></td></tr> <tr><td><code>BlockingReaderWriterQueue&lt;T&gt;</code></td> <td>阻塞消费</td> <td>基础版全部接口 + <code>wait_dequeue</code>、<code>wait_dequeue_timed</code></td></tr> <tr><td><code>BlockingReaderWriterCircularBuffer&lt;T&gt;</code></td> <td>固定容量，两侧可阻塞</td> <td><code>wait_enqueue</code>、<code>wait_enqueue_timed</code> 与阻塞出队接口</td></tr></tbody></table> <ul><li><strong>基础版</strong>：<code>enqueue</code> 满时自动扩容；<code>try_enqueue</code> 只使用预分配容量，满则返回 false，全程不分配内存。两者配合可以做到「平时走快速路径，异常时降级处理」。</li> <li><strong>阻塞版</strong>：消费者在队列为空时可以用 <code>wait_dequeue</code> 挂起等待，<code>wait_dequeue_timed</code> 支持超时，省去手写轮询。</li> <li><strong>环形缓冲版</strong>：固定容量、从不扩容，生产者在队列满时也可以阻塞等待（<code>wait_enqueue</code>），适合要求内存用量有上界的场景。</li></ul> <h2 id="使用要点" tabindex="-1">使用要点 <a class="header-anchor" href="#使用要点" aria-label="Permalink to &quot;使用要点&quot;">​</a></h2> <p><strong>编译器要求</strong>：C++11 及以上；官方支持 MSVC 2010+、GCC 4.7+（4.6 因原子 fence 相关缺陷被明确排除）、ICC 13+，其余符合 C++11 标准的编译器一般可用。</p> <p><strong>阻塞接口的生命周期约束</strong>：<code>wait_dequeue</code> 阻塞期间销毁队列是未定义行为。使用阻塞版本时，要么保证队列最终一定会有新元素（或让队列具有静态生存期），要么用 <code>wait_dequeue_timed</code> 控制等待上界，并在退出路径上确保没有线程仍在等待。</p> <p><strong>平台要求</strong>：依赖对齐的整数与指针访问具有原子性，适用于 x86、ARM、PowerPC 等主流架构；弱内存序的 DEC Alpha 官方明确不支持。</p> <p><strong>SPSC 是硬约束</strong>：队列不支持多个生产者或多个消费者，两个生产者同时 <code>enqueue</code> 是数据竞争。多对多场景应改用同一作者的 moodycamel <code>ConcurrentQueue</code>。</p> <h2 id="集成方式" tabindex="-1">集成方式 <a class="header-anchor" href="#集成方式" aria-label="Permalink to &quot;集成方式&quot;">​</a></h2> <ol><li><strong>直接包含头文件</strong>：把两个 <code>.h</code> 放进项目，<code>#include &quot;readerwriterqueue.h&quot;</code> 即可，无外部依赖、无构建脚本改动，适合快速验证。</li> <li><strong>CMake FetchContent</strong>：在 <code>CMakeLists.txt</code> 里声明后自动拉取与跟踪版本，正式项目推荐。</li> <li><strong>系统安装</strong>：通过 CMake 安装到系统目录后，像标准库一样 <code>#include &lt;readerwriterqueue/readerwriterqueue.h&gt;</code>。</li></ol> <h2 id="什么时候选它" tabindex="-1">什么时候选它 <a class="header-anchor" href="#什么时候选它" aria-label="Permalink to &quot;什么时候选它&quot;">​</a></h2> <ul><li><strong>两个线程、单向高频传数据</strong>：首选。接口小、行为可预期、头文件即插即用。</li> <li><strong>想理解它为什么快</strong>：SPSC 的「读写索引各归一个线程」性质与 acquire/release 内存序配对是全部核心，《无锁环形队列设计与实现（SPSC 与 MPMC）》一文有从零手写的完整讨论；对照阅读会发现这个库的每条设计都对应手写实现里的一个取舍。</li> <li><strong>多生产者或多消费者</strong>：改用 moodycamel <code>ConcurrentQueue</code>，不要尝试在 SPSC 队列上 workaround。</li></ul> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>SPSC 专用：一个生产者线程、一个消费者线程，角色固定；多对多场景用 <code>ConcurrentQueue</code>。</li> <li><code>try_enqueue</code> 不分配内存、失败即返回 false，实时路径用它；<code>enqueue</code> 满时自动扩容。</li> <li>入队出队无 CAS 循环、O(1)，强内存模型架构上内存屏障近乎免费。</li> <li>阻塞版 <code>wait_dequeue</code> 等待期间销毁队列是未定义行为，退出路径要保证没有线程仍在等待。</li> <li>集成零门槛：直接拷贝头文件即可起步，正式项目用 CMake FetchContent 管理版本。</li></ul> <p>（内容依据 readerwriterqueue 官方 README 与项目文档整理。）</p>',43)])])}const C=r(a,[["render",c]]);export{q as __pageData,C as default};
